const $ = id => document.getElementById(id);
const START='2026-11-02',ZONE='America/Santiago',STORE='entre-lineas-v1',ROUND_SIZE=10;
const LEVELS={suave:{name:'Suave',description:'Una lectura amable: definiciones y mecanismos directos.'},intermedio:{name:'Intermedio',description:'Otra vuelta: fragmentos, sustituciones y pistas menos evidentes.'},desafio:{name:'Desafío',description:'Paso a paso: combina operaciones para encontrar la respuesta.'}};
function dayKey(d=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function offset(key){return Math.round((Date.parse(key+'T12:00:00Z')-Date.parse(START+'T12:00:00Z'))/86400000)}
function normalize(s){return s.toUpperCase().replace(/[ÁÀÄÂ]/g,'A').replace(/[ÉÈËÊ]/g,'E').replace(/[ÍÌÏÎ]/g,'I').replace(/[ÓÒÖÔ]/g,'O').replace(/[ÚÙÜÛ]/g,'U').replace(/[^A-ZÑ]/g,'').slice(0,5)}
let level='suave',mode='free',storageOK=true;
let data={games:{},theme:'dark',level:'suave',roundViews:{}};
try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved&&saved.games&&typeof saved.games==='object'&&!Array.isArray(saved.games)){data.games=saved.games;data.theme=saved.theme==='light'?'light':'dark';level=LEVELS[saved.level]?saved.level:'suave';data.level=level;if(saved.roundViews&&typeof saved.roundViews==='object'&&!Array.isArray(saved.roundViews))data.roundViews=saved.roundViews}}catch{storageOK=false}
function bank(){return PUZZLE_BANKS[level]}
function gameKey(i,l=level){return l==='suave'?String(i):l+':'+i}
function storedGame(i,l=level){return data.games[gameKey(i,l)]}
function finished(g){return g?.status==='won'||g?.status==='givenup'}
function game(i=selected){const key=gameKey(i);let g=data.games[key];if(!g||typeof g!=='object')g=data.games[key]={answer:'',tries:0,hints:0,status:'playing',guesses:[]};g.answer=typeof g.answer==='string'?normalize(g.answer):'';g.tries=Number.isInteger(g.tries)&&g.tries>=0?g.tries:0;g.hints=Number.isInteger(g.hints)?Math.min(3,Math.max(0,g.hints)):0;g.guesses=Array.isArray(g.guesses)?g.guesses:[];if(!['playing','won','givenup'].includes(g.status))g.status='playing';return g}
function save(){try{localStorage.setItem(STORE,JSON.stringify(data))}catch{storageOK=false;$('message').textContent='No se pudo guardar: mantén esta página abierta para conservar la partida.'}}
function firstPending(){return bank().findIndex((_,i)=>!finished(storedGame(i)))}
function initialSelection(){const saved=data.roundViews[level];return Number.isInteger(saved)&&saved>=0&&saved<bank().length?saved:Math.max(0,firstPending())}
let selected=initialSelection(),cursor=0,today=offset(dayKey()),currentDate=dayKey();
function roundNumber(i=selected){return Math.floor(i/ROUND_SIZE)}
function roundCount(){return Math.ceil(bank().length/ROUND_SIZE)}
function roundIndices(r=roundNumber()){return Array.from({length:Math.min(ROUND_SIZE,bank().length-r*ROUND_SIZE)},(_,n)=>r*ROUND_SIZE+n)}
function roundStats(r=roundNumber()){const ids=roundIndices(r),entries=ids.map(i=>storedGame(i));const won=entries.filter(g=>g?.status==='won').length,revealed=entries.filter(g=>g?.status==='givenup').length;return {total:ids.length,won,revealed,completed:won+revealed,hints:entries.reduce((n,g)=>n+(g?.hints||0),0),tries:entries.reduce((n,g)=>n+(g?.tries||0),0)}}
function firstInRound(r){const ids=roundIndices(r);return ids.find(i=>!finished(storedGame(i)))??ids[0]}
function nextRoundIndex(){for(let n=1;n<=roundCount();n++){const r=(roundNumber()+n)%roundCount();if(roundStats(r).completed<roundStats(r).total)return r}return -1}
function select(i){if(!Number.isInteger(i)||i<0||i>=bank().length)return;selected=i;cursor=game().answer.length;data.roundViews[level]=i;save();close();render()}
function startRound(r){if(Number.isInteger(r)&&r>=0&&r<roundCount())select(firstInRound(r))}
function tiles(){const g=game(),value=finished(g)?bank()[selected][0]:g.answer;$('tiles').replaceChildren(...Array.from({length:5},(_,i)=>{const e=document.createElement('span');e.className='tile'+(finished(g)?' solved':i===Math.min(cursor,4)?' current':'');e.textContent=value[i]||'';return e}))}
function hintText(){const g=game(),p=bank()[selected];return [p[2],p[3],'La primera letra es '+p[0][0]+'.'].slice(0,g.hints)}
function renderRound(){
  const r=roundNumber(),s=roundStats(),done=s.completed===s.total;
  $('round-label').textContent='RONDA '+(r+1)+' DE '+roundCount()+' · '+LEVELS[level].name.toUpperCase();
  $('round-progress').textContent=s.completed+' de '+s.total+' completados';$('round-meter').max=s.total;$('round-meter').value=s.completed;
  $('round-steps').replaceChildren(...roundIndices().map((i,n)=>{const b=document.createElement('button'),g=storedGame(i),status=g?.status==='won'?'resuelto':g?.status==='givenup'?'revelado':'pendiente';b.textContent=String(n+1);b.className='round-step '+(g?.status||'playing');b.setAttribute('aria-label','Acertijo '+(n+1)+' de '+s.total+', '+status);if(i===selected)b.setAttribute('aria-current','step');b.onclick=()=>select(i);return b}));
  $('round-summary').hidden=!done;$('round-summary').replaceChildren();
  if(done){const h=document.createElement('h3');h.textContent='Ronda completada · '+s.completed+'/'+s.total;const p=document.createElement('p');p.textContent=s.won+' resueltos · '+s.revealed+' revelados · '+s.hints+' pistas usadas · '+s.tries+' intentos.';const note=document.createElement('p');note.textContent=nextRoundIndex()>=0?'Una buena pausa… o diez nuevos descubrimientos.':'Completaste todas las rondas de este nivel. Puedes probar otra dificultad o repasar las explicaciones.';$('round-summary').append(h,p,note)}
  $('next-puzzle').disabled=done&&nextRoundIndex()<0;
  $('next-puzzle').textContent=done?(nextRoundIndex()<0?'Nivel completado ✓':'Jugar otra ronda de 10 →'):finished(game())?'Continuar la ronda →':'Dejar para después →';
  $('round-position').textContent='Acertijo '+(selected%ROUND_SIZE+1)+' de '+s.total;
}
function renderSelectors(){for(const l of Object.keys(LEVELS))$('level-'+l).setAttribute('aria-pressed',String(l===level));$('level-description').textContent=LEVELS[level].description;$('daily-mode').setAttribute('aria-pressed',String(mode==='daily'));$('free-mode').setAttribute('aria-pressed',String(mode==='free'));$('free-controls').hidden=false;$('library-count').textContent=statistics().pending+' acertijos pendientes · '+roundCount()+' rondas de '+ROUND_SIZE+' · '+LEVELS[level].name}
function render(){
  renderSelectors();renderRound();const g=game(),p=bank()[selected],done=finished(g);
  $('puzzle-title').textContent=mode==='daily'?'Tu ronda sugerida':'Una ronda, diez descubrimientos';$('date').textContent=mode==='daily'?new Intl.DateTimeFormat('es-CL',{timeZone:ZONE,day:'numeric',month:'long'}).format(new Date()):'A TU RITMO';
  $('number').textContent='ACERTIJO '+(selected%ROUND_SIZE+1)+' DE '+roundStats().total;$('difficulty').textContent=LEVELS[level].name.toUpperCase()+' · CINCO LETRAS';$('clue').textContent=p[1];$('answer').value=g.answer;$('answer').disabled=done;$('check').disabled=done;$('hint').disabled=done||g.hints>=3;$('giveup').disabled=done;$('attempts').textContent=g.tries+' intento'+(g.tries===1?'':'s');$('keyboard').querySelectorAll('button').forEach(b=>b.disabled=done);
  $('hint-box').hidden=!g.hints;$('hint-box').replaceChildren(...hintText().map((t,i)=>{const e=document.createElement('p');e.textContent=(i+1)+'. '+t;return e}));$('result').hidden=!done;$('result').replaceChildren();
  if(done){const title=document.createElement('h3');title.textContent=g.status==='won'?'Ese era el «¡ajá!» · '+p[0]:'Una nueva forma de verlo · '+p[0];const exp=document.createElement('p');exp.textContent=p[4];const share=document.createElement('button');share.className='secondary';share.textContent='Compartir resultado';share.onclick=shareResult;$('result').append(title,exp,share);$('message').textContent=roundStats().completed===roundStats().total?'¡Diez de diez completados! Tu resumen está al final.':'Este ya está. Continúa con el siguiente de la ronda.'}else $('message').textContent=storageOK?'Sin prisa. Puedes pausar y retomar esta ronda.':'Tu navegador no permite guardar el progreso.';
  tiles();$('next').textContent='Rondas de 10 · juega varias al día';
}
function syncInput(){const g=game();g.answer=normalize($('answer').value);cursor=g.answer.length;$('answer').value=g.answer;save();tiles()}
$('answer').addEventListener('input',syncInput);$('answer').addEventListener('click',()=>{cursor=$('answer').selectionStart;tiles()});$('answer').addEventListener('keyup',()=>{cursor=$('answer').selectionStart;tiles()});
$('answer-form').onsubmit=e=>{e.preventDefault();const g=game();if(finished(g))return;if(g.answer.length!==5){$('message').textContent='Completa las cinco letras antes de comprobar.';$('answer').focus();return}if(g.guesses.includes(g.answer)){$('message').textContent='Ya probaste esa palabra. Busca otra lectura de la frase.';return}g.tries++;g.guesses.push(g.answer);if(g.answer===bank()[selected][0])g.status='won';save();render();if(!finished(g)){$('message').textContent='Todavía no. Prueba otra lectura; tienes intentos ilimitados.';$('answer').focus();$('answer').select()}};
['QWERTYUIOP','ASDFGHJKLÑ','ZXCVBNM⌫'].forEach(row=>{const el=document.createElement('div');el.className='keyrow';[...row].forEach(letter=>{const b=document.createElement('button');b.className='key'+(letter==='⌫'?' back':'');b.textContent=letter;b.setAttribute('aria-label',letter==='⌫'?'Borrar letra':letter);b.onclick=()=>{if(finished(game()))return;const input=$('answer');let start=input.selectionStart??input.value.length,end=input.selectionEnd??start;if(letter==='⌫'){if(start===end&&start>0)start--;input.setRangeText('',start,end,'end')}else input.setRangeText(letter,start,end,'end');const pos=input.selectionStart;game().answer=normalize(input.value);input.value=game().answer;cursor=Math.min(pos,5);input.setSelectionRange(cursor,cursor);save();tiles()};el.append(b)});$('keyboard').append(el)});
function open(html){$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function close(){$('modal').close()}
$('close').onclick=close;$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}};
$('hint').onclick=()=>{const g=game();if(finished(g)||g.hints>=3)return;g.hints++;save();render()};
$('giveup').onclick=()=>{open('<h2>¿Ver esta solución?</h2><p>Este acertijo quedará revelado y contará como completado, pero no como resuelto. Los otros nueve siguen disponibles.</p><button class="secondary" id="keep">Seguir pensando</button><button class="secondary" id="reveal">Sí, ver la solución</button>');$('keep').onclick=close;$('reveal').onclick=()=>{game().status='givenup';save();close();render()}};
function suggestedRound(){today=offset(dayKey());const initial=((today%roundCount())+roundCount())%roundCount();for(let n=0;n<roundCount();n++){const r=(initial+n)%roundCount();if(roundStats(r).completed<roundStats(r).total)return r}return -1}
$('today').onclick=()=>{mode='daily';const r=suggestedRound();if(r<0){render();open('<h2>¡Todas las rondas completadas!</h2><p>No quedan acertijos nuevos en este nivel. Prueba otra dificultad o vuelve al archivo para repasar las soluciones.</p>');return}startRound(r)};
function showRounds(){open('<h2>Tus rondas · '+LEVELS[level].name+'</h2><p>Cada ronda tiene diez acertijos. Puedes jugar varias al día y retomar las que dejes a medias.</p><div class="archive-list" id="round-list"></div>');for(let r=0;r<roundCount();r++){const b=document.createElement('button'),s=roundStats(r);b.className='archive-item';b.textContent='Ronda '+(r+1)+' · '+s.completed+'/'+s.total+' completados'+(s.completed===s.total?' ✓':'');b.onclick=()=>{mode='free';startRound(r)};$('round-list').append(b)}}
$('archive').onclick=showRounds;$('library').onclick=showRounds;
function statistics(){const entries=bank().map((_,i)=>storedGame(i)).filter(Boolean),won=entries.filter(g=>g.status==='won');let rounds=0;for(let r=0;r<roundCount();r++){const s=roundStats(r);if(s.completed===s.total)rounds++}return {played:entries.filter(g=>g.tries>0||g.hints>0||finished(g)).length,won:won.length,pending:bank().length-entries.filter(finished).length,rounds,assisted:won.filter(g=>g.hints>0).length}}
$('stats').onclick=()=>{const s=statistics();open('<h2>Tu rincón · '+LEVELS[level].name+'</h2><div class="stat-grid"><div><b>'+s.rounds+'</b>rondas completadas</div><div><b>'+s.won+'</b>acertijos resueltos</div><div><b>'+s.pending+'</b>pendientes</div><div><b>'+s.assisted+'</b>resueltos con ayuda</div></div><p>Una ronda se completa al terminar sus diez acertijos. Revelar una solución cuenta para avanzar, pero no suma un acierto. Los resultados anteriores se conservan.</p><p>Todo se guarda en este navegador y dispositivo. Sin cuentas ni seguimiento. Borrar los datos del navegador elimina tu historial.</p>')};
$('help').onclick=()=>open('<h2>Diez oportunidades de decir «¡ajá!»</h2><p>Elige Suave, Intermedio o Desafío y juega una <strong>ronda de diez acertijos</strong>. El indicador muestra tu posición y cuántos has completado. Los diez botones permiten moverte dentro de la ronda.</p><p>Cada frase combina una <strong>definición</strong> y un <strong>juego de palabras</strong>. Ejemplo: «Saco, revuelto, trae desorden (4)». Reordena SACO para obtener CAOS, que significa desorden.</p><p>Escribe cinco letras y pulsa Comprobar o Enter. Hay intentos ilimitados, tres pistas y una explicación al terminar. Se aceptan tildes al escribir; la Ñ se conserva. «Dejar para después» pasa a otro acertijo de la ronda sin marcar el actual como terminado.</p><p>Al completar los diez verás tus aciertos, soluciones reveladas, pistas e intentos. Puedes jugar otra ronda ese mismo día. La colección inicial tiene 90 acertijos: tres rondas por cada uno de los tres niveles.</p><p>La ronda sugerida prioriza un bloque según el día de Santiago y salta los bloques que ya completaste; no significa que haya diez acertijos nuevos cada día. El archivo permite elegir cualquier ronda y volver a sus explicaciones. El juego no recicla acertijos terminados como pendientes.</p>');
function applyTheme(){document.body.classList.toggle('light',data.theme==='light');$('theme').textContent=data.theme==='light'?'☾':'☼';$('theme').setAttribute('aria-label',data.theme==='light'?'Activar tema oscuro':'Activar tema claro');document.querySelector('meta[name="theme-color"]').content=data.theme==='light'?'#f7f4ec':'#121313'}
$('theme').onclick=()=>{data.theme=data.theme==='light'?'dark':'light';save();applyTheme()};
async function shareResult(){const g=game(),s=roundStats(),text='Entre líneas · '+LEVELS[level].name+' · Ronda '+(roundNumber()+1)+'\n'+(s.completed===s.total?s.won+'/10 resueltos · '+s.revealed+' revelados':s.completed+'/10 completados · acertijo '+(selected%ROUND_SIZE+1)+(g.status==='won'?' resuelto':' revelado'))+'\nUn pequeño ritual para Paula.';try{if(navigator.share)await navigator.share({title:'Entre líneas',text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);$('message').textContent='Resultado copiado, sin revelar respuestas.'}else throw Error()}catch(e){if(e.name!=='AbortError'){open('<h2>Tu resultado</h2><p id="share-text"></p>');$('share-text').textContent=text}}}
function nextPending(){const ids=roundIndices(),position=ids.indexOf(selected);for(let n=1;n<=ids.length;n++){const i=ids[(position+n)%ids.length];if(!finished(storedGame(i))){select(i);return}}const r=nextRoundIndex();if(r>=0){mode='free';startRound(r)}else{render();open('<h2>¡Nivel completado!</h2><p>Terminaste sus tres rondas. Puedes elegir otra dificultad o repasar las explicaciones desde Tus rondas.</p>')}}
function chooseLevel(l){if(!LEVELS[l])return;data.roundViews[level]=selected;level=l;data.level=l;selected=initialSelection();cursor=game().answer.length;save();close();render()}
for(const l of Object.keys(LEVELS))$('level-'+l).onclick=()=>chooseLevel(l);
$('daily-mode').onclick=()=>$('today').click();$('free-mode').onclick=()=>{mode='free';render()};$('next-puzzle').onclick=nextPending;
setInterval(()=>{const key=dayKey();if(key!==currentDate){currentDate=key;today=offset(key);render()}},15000);
window.addEventListener('storage',e=>{if(e.key===STORE&&e.newValue){try{const newer=JSON.parse(e.newValue);if(newer&&newer.games&&typeof newer.games==='object'&&!Array.isArray(newer.games)){data.games=newer.games;data.theme=newer.theme==='light'?'light':'dark';applyTheme();render()}}catch{}}});
applyTheme();render();
